// Mint the org operational keypair, and the passphrase that wraps it, into the credential store.
//
// VAULT.md:112 has cited this script since W44 and it has never existed — the org key in service
// was generated by hand, which is why nothing recorded its parameters and why the one in
// `records/org-key.json` ended up committed to a repository that later went public.
//
//   npm run org:key                # report only — says what it would write, writes nothing
//   npm run org:key -- --confirm   # generate, write, read back and verify
//
// WHERE IT WRITES, AND WHY NOT HERE. `$LEXI_CREDENTIALS_DIR/org-key.json`, never a path inside
// this repository. The private half of this keypair holds a recovery envelope on every vault, so a
// copy of this file plus its passphrase opens every patient record in the store it serves. The old
// one was committed under a since-withdrawn "this is a private repo" premise (VAULT.md:57); a
// generator that defaults into the tree is how that premise gets re-adopted by accident.
//
// THE PASSPHRASE IS NEVER PRINTED. It goes to a sibling `org-key.passphrase` at mode 0600 and this
// script reports its shape — length and character class — and nothing else. A secret echoed to a
// terminal is a secret in a scrollback buffer, a terminal log and whatever captured the session, and
// an operator who needs it next wants it in a pipe rather than in their eyes:
//
//   ORG_KEY_PASSPHRASE="$(cat "$LEXI_CREDENTIALS_DIR/org-key.passphrase")" npm run vault:rekey
//
// IT DOES NOT GO TO ACTIONS, corrected 2026-10-07. These two lines used to read
// `gh secret set ORG_KEY_PASSPHRASE -R tinytars/lexi < …`, and that instruction was wrong in the
// direction that matters: no org key FILE ever reaches a hosted runner — org-key.ts:28 resolves
// ORG_KEY_PATH or a credential store's org-key.json with no in-repo fallback, and no workflow in this
// repository sets any of them — so the secret has no counterpart there and opens nothing. The five ops
// in .github/workflows/ops.yml that would need it are operator-only for exactly that reason, which
// that file now records. The destination is the credential store and the commit to plover-keys.
//
// IT REFUSES TO OVERWRITE. An existing org-key.json is the key some vault's only recovery envelope
// is wrapped to, and replacing the file is not the same operation as rotating the envelopes — doing
// the first without the second strands every vault. `--force` is deliberately absent: move the old
// file aside by hand, which is a step somebody has to have meant.
import "./load-creds";
import { existsSync, mkdirSync, writeFileSync, readFileSync, statSync } from "node:fs";
import { dirname } from "node:path";
import { randomInt } from "node:crypto";
import {
  generateAccountKeypair,
  deriveKekFromPassword,
  wrapPrivateKey,
  unwrapPrivateKey,
} from "@tinytars/vault/crypto";
import { SALT_LEN, PBKDF2_ITERATIONS } from "@tinytars/vault/kdf";
import type { OrgKeyFile } from "./org-key";
import { credentialPath, credentialsDir } from "./creds-dir";

// Resolved through the shared resolver rather than re-spelled here: this script and org-key.ts have
// to agree on where the file goes, and a generator that writes somewhere the loader does not look
// fails silently with both halves looking correct.
const keyPath = process.env.ORG_KEY_PATH ?? credentialPath("org-key.json");
const passPath = keyPath.replace(/\.json$/, ".passphrase");

// 32 characters from a 64-symbol alphabet is 192 bits, well past the 128 the AES-GCM key below is
// worth, so the passphrase is not the weak link. No ambiguous glyphs: this value gets read aloud and
// retyped during a recovery, and `l`/`1` and `O`/`0` are where that goes wrong.
const ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789-_@#";
const PASS_LEN = 32;

/** `randomInt` rather than arithmetic on random bytes — modulo over 256 biases the first 16 symbols. */
function mintPassphrase(): string {
  let out = "";
  for (let i = 0; i < PASS_LEN; i++) out += ALPHABET[randomInt(ALPHABET.length)];
  return out;
}

const bytesToHex = (u: Uint8Array): string => Buffer.from(u).toString("hex");
const hexToBytes = (h: string): Uint8Array => Uint8Array.from(Buffer.from(h, "hex"));
const bytesToB64 = (u: Uint8Array): string => Buffer.from(u).toString("base64");
const b64ToBytes = (b: string): Uint8Array => Uint8Array.from(Buffer.from(b, "base64"));

/** Length and character classes, never the value. What a reader needs to confirm a handover worked. */
function shapeOf(secret: string): string {
  const classes = [
    /[a-z]/.test(secret) && "lower",
    /[A-Z]/.test(secret) && "upper",
    /[0-9]/.test(secret) && "digit",
    /[^A-Za-z0-9]/.test(secret) && "symbol",
  ].filter(Boolean);
  return `${secret.length} characters, ${classes.join("+")}`;
}

async function main(): Promise<void> {
  const confirm = process.argv.includes("--confirm");

  console.log(`org key:    ${keyPath}`);
  console.log(`passphrase: ${passPath}`);

  if (existsSync(keyPath)) {
    console.error(
      `\nrefusing to overwrite ${keyPath}\n` +
        `That file is the key some vault's only recovery envelope is wrapped to. Replacing it is not\n` +
        `the same operation as re-minting those envelopes, and doing this one alone strands them.\n` +
        `Move it aside by hand if that is really what you mean.`,
    );
    process.exit(1);
  }
  if (!existsSync(credentialsDir())) {
    // The PRIMARY store, deliberately: a new key is a write, and a write has no business
    // landing in the estate's shared store now that this product has its own.
    console.error(
      `\nno credential store at ${credentialsDir()} — clone tinytars/lexi-keys there, ` +
        `or point LEXI_CREDENTIALS_DIR at it`,
    );
    process.exit(1);
  }

  if (!confirm) {
    console.log(`\nwould generate a P-256 ECDH keypair and a ${PASS_LEN}-character passphrase,`);
    console.log(`wrap the private half under PBKDF2-SHA256/${PBKDF2_ITERATIONS} and write both files.`);
    console.log(`\nnothing written. re-run with --confirm.`);
    return;
  }

  const pair = await generateAccountKeypair();
  const passphrase = mintPassphrase();
  const salt = globalThis.crypto.getRandomValues(new Uint8Array(SALT_LEN));
  const kek = await deriveKekFromPassword(passphrase, salt);
  const wrapped = await wrapPrivateKey(pair.privateKey, kek);

  const file: OrgKeyFile = {
    publicKeyJwk: pair.publicKeyJwk,
    wrappedPrivateKey: bytesToB64(wrapped),
    kdfParams: { salt: bytesToHex(salt), iterations: PBKDF2_ITERATIONS },
    createdAt: new Date().toISOString(),
  };

  // The passphrase lands BEFORE the key it opens. The reverse ordering loses a keypair nobody can
  // unwrap if the second write fails, and an orphaned passphrase costs nothing — the same argument
  // raw-encrypt-backfill.ts makes for saving a content key before sealing its object.
  mkdirSync(dirname(passPath), { recursive: true });
  writeFileSync(passPath, `${passphrase}\n`, { mode: 0o600 });
  writeFileSync(keyPath, `${JSON.stringify(file, null, 2)}\n`, { mode: 0o600 });

  // Read back from disk rather than trusting the handles above: this asserts the bytes that landed
  // are the bytes that unwrap, which is the one property a later recovery depends on.
  const onDisk = JSON.parse(readFileSync(keyPath, "utf8")) as OrgKeyFile;
  const readPass = readFileSync(passPath, "utf8").trimEnd();
  const rekek = await deriveKekFromPassword(readPass, hexToBytes(onDisk.kdfParams.salt));
  await unwrapPrivateKey(b64ToBytes(onDisk.wrappedPrivateKey), rekek);

  console.log(`\nwrote and verified.`);
  console.log(`  public key:  ${(onDisk.publicKeyJwk as { x?: string }).x?.slice(0, 16)}… (P-256 x, truncated)`);
  console.log(`  kdf:         PBKDF2-SHA256/${onDisk.kdfParams.iterations}, ${SALT_LEN}-byte salt`);
  console.log(`  passphrase:  ${shapeOf(readPass)}, mode ${(statSync(passPath).mode & 0o777).toString(8)}`);
  console.log(`\nnext: commit both files to plover-keys and add them to its README inventory.`);
  console.log(`not an Actions secret \u2014 no org key file reaches CI, so it would open nothing there.`);
  console.log(`read it without a terminal seeing it:  ORG_KEY_PASSPHRASE="$(cat ${passPath})" \u2026`);
}

main().catch((e) => {
  console.error(e instanceof Error ? e.message : String(e));
  process.exit(1);
});
